window.lucide={createIcons:function(){document.querySelectorAll('i[data-lucide]').forEach(function(el){var n=el.getAttribute('data-lucide');var s=I[n];if(!s)return;var st=el.getAttribute('style')||'';var w='18',h='18';var wm=st.match(/width\s*:\s*(\d+)px/);if(wm){w=wm[1];h=wm[1];}var cs='';var cm=st.match(/color\s*:\s*([^;]+)/);if(cm)cs=' style="color:'+cm[1].trim()+'"';var svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('width',w);svg.setAttribute('height',h);svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','2');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');if(cs){var m=cs.match(/color:\s*([^"]+)/);if(m)svg.style.color=m[1].trim();}svg.innerHTML=s;el.replaceWith(svg);});}};
