window.currentSearchQuery = '';
window.currentSortBy = '';
window.currentCategoryFilter = '';
window.currentSupplierFilter = '';
window.currentStatusFilter = '';

window.getFilteredAndSorted = function() {
  let items = window.products || [];
  if (window.currentFilter && window.currentFilter !== 'All') {
    items = items.filter(p => {
      if (window.currentFilter === 'In stock') return p.status && p.status[1] === 'In stock';
      if (window.currentFilter === 'Running out') return p.status && (p.status[1] === 'Running out' || p.status[1] === 'Low stock');
      if (window.currentFilter === 'Out of stock') return p.status && p.status[1] === 'Out of stock';
      if (window.currentFilter === 'Slow movers') return p.status && p.status[1] === 'Slow mover';
      if (window.currentFilter === 'Hidden') return p.status && p.status[1] === 'Hidden';
      return true;
    });
  }
  const q = (window.currentSearchQuery || '').toLowerCase().trim();
  if (q) {
    items = items.filter(p =>
      (p.name || '').toLowerCase().includes(q) ||
      (p.sku || '').toLowerCase().includes(q) ||
      (p.category || '').toLowerCase().includes(q) ||
      (p.barcode || '').toLowerCase().includes(q)
    );
  }
  if (window.currentCategoryFilter)
    items = items.filter(p => (p.category || '') === window.currentCategoryFilter);
  if (window.currentSupplierFilter)
    items = items.filter(p => (p.supplier_name || '') === window.currentSupplierFilter);
  if (window.currentStatusFilter)
    items = items.filter(p => p.status && p.status[1].toLowerCase().includes(window.currentStatusFilter.toLowerCase()));
  const s = window.currentSortBy;
  if (s === 'name-asc') items = [...items].sort((a,b) => (a.name||'').localeCompare(b.name||''));
  else if (s === 'name-desc') items = [...items].sort((a,b) => (b.name||'').localeCompare(a.name||''));
  else if (s === 'stock-asc') items = [...items].sort((a,b) => (a.avail||0) - (b.avail||0));
  else if (s === 'stock-desc') items = [...items].sort((a,b) => (b.avail||0) - (a.avail||0));
  else if (s === 'price-asc') items = [...items].sort((a,b) => (a.price||0) - (b.price||0));
  else if (s === 'price-desc') items = [...items].sort((a,b) => (b.price||0) - (a.price||0));
  return items;
};

window.onProductSearch = function(input) {
  window.currentSearchQuery = input.value;
  window.currentPage = 1;
  const clearBtn = document.getElementById('searchClearBtn');
  if (clearBtn) clearBtn.classList.toggle('show', input.value.length > 0);
  if (window.renderRows) window.renderRows();
};

window.clearProductSearch = function() {
  const inp = document.getElementById('productSearchInput');
  if (inp) { inp.value = ''; inp.focus(); }
  const clearBtn = document.getElementById('searchClearBtn');
  if (clearBtn) clearBtn.classList.remove('show');
  window.currentSearchQuery = '';
  window.currentPage = 1;
  if (window.renderRows) window.renderRows();
};

window.togglePanel = function(showId, hideId) {
  const el = document.getElementById(showId);
  const other = document.getElementById(hideId);
  if (other) other.classList.remove('show');
  if (el) el.classList.toggle('show');
};

document.addEventListener('click', function(e) {
  if (!e.target.closest('#filterBtn') && !e.target.closest('#filterPanel')) {
    const fp = document.getElementById('filterPanel');
    if (fp) fp.classList.remove('show');
  }
  if (!e.target.closest('#sortBtn') && !e.target.closest('#sortPanel')) {
    const sp = document.getElementById('sortPanel');
    if (sp) sp.classList.remove('show');
  }
}, true);

window.applyAllFilters = function() {
  const cat = document.getElementById('filterCategory');
  const sup = document.getElementById('filterSupplier');
  const st = document.getElementById('filterStatus');
  window.currentCategoryFilter = cat ? cat.value : '';
  window.currentSupplierFilter = sup ? sup.value : '';
  window.currentStatusFilter = st ? st.value : '';
  window.currentPage = 1;
  if (window.renderRows) window.renderRows();
  const btn = document.getElementById('filterBtn');
  const hasFilter = window.currentCategoryFilter || window.currentSupplierFilter || window.currentStatusFilter;
  if (btn) btn.style.borderColor = hasFilter ? 'var(--jade-300)' : '';
};

window.clearFilters = function() {
  window.currentCategoryFilter = '';
  window.currentSupplierFilter = '';
  window.currentStatusFilter = '';
  ['filterCategory','filterSupplier','filterStatus'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  const btn = document.getElementById('filterBtn');
  if (btn) btn.style.borderColor = '';
  window.currentPage = 1;
  if (window.renderRows) window.renderRows();
};

window.setSort = function(btn, sortBy) {
  window.currentSortBy = sortBy;
  document.querySelectorAll('.sort-option').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  const sp = document.getElementById('sortPanel');
  if (sp) sp.classList.remove('show');
  const sortBtn = document.getElementById('sortBtn');
  if (sortBtn) sortBtn.style.borderColor = sortBy ? 'var(--jade-300)' : '';
  window.currentPage = 1;
  if (window.renderRows) window.renderRows();
};

window.populateFilterDropdowns = function() {
  const prods = window.products || [];
  const cats = [...new Set(prods.map(p => p.category).filter(Boolean))].sort();
  const sups = [...new Set(prods.map(p => p.supplier_name).filter(Boolean))].sort();
  const catSel = document.getElementById('filterCategory');
  if (catSel) {
    const prev = catSel.value;
    catSel.innerHTML = '<option value="">All categories</option>' +
      cats.map(c => '<option value="' + c + '">' + c + '</option>').join('');
    catSel.value = prev;
  }
  const supSel = document.getElementById('filterSupplier');
  if (supSel) {
    const prev = supSel.value;
    supSel.innerHTML = '<option value="">All suppliers</option>' +
      sups.map(s => '<option value="' + s + '">' + s + '</option>').join('');
    supSel.value = prev;
  }
};

window.populateAddProductSupplier = function() {
  const sel = document.getElementById('addProdSupplier');
  if (!sel) return;
  const vendors = window.vendors || [];
  sel.innerHTML = '<option value="">No supplier</option>' +
    vendors.map(v => '<option value="' + (v.id||'') + '">' + v.name + '</option>').join('');
};
